// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 selector) public {
        // General rule: for EVERY selector queried, whenever supportsInterface returns true,
        // it must report support for both IAccessControl and IERC165 interface ids on the
        // canonical query selectors; in particular supportsInterface(IAccessControl.interfaceId)
        // is always true. The mutant drops the IAccessControl check, so it returns false there.
        bool okAC = c.supportsInterface(type(IAccessControl).interfaceId);
        bool ok165 = c.supportsInterface(type(IERC165).interfaceId);
        // touch the fuzzed selector through the public surface so the input space is exercised
        c.supportsInterface(selector);
        assertTrue(okAC && ok165);
    }
}
